package com. topdon. module. thermal. ir. video import android. graphics. Bitmap import com. topdon. lib. core. utils. BitmapUtils import com. infisense. usbir. view. CameraView import com. infisense. usbir. view. TemperatureView import com. topdon. lib. core. config. FileConfig import com. topdon. module. thermal. ir. video. media. Encoder import com. topdon. module. thermal. ir. video. media. MP4Encoder import io. reactivex. Observable import io. reactivex. android. schedulers. AndroidSchedulers import io. reactivex. disposables. Disposable import java. io. File import java. util. * import java. util. concurrent. TimeUnit / *  *  *  * bitmap -> mp4 * / class VideoRecordMedia (private var cameraView: CameraView, private var temperatureView: TemperatureView) : VideoRecord () { private lateinit var exportDisposable: Disposable private var encoder: Encoder = MP4Encoder () private var isRunning = false var width = 480 var height = 640 init { encoder. setFrameDelay (25) width = 480 height = width * cameraView. height / cameraView. width // height if (height % 2 == 1) { height -= 1 } } override fun startRecord () { val downloadDir = FileConfig. lineGalleryDir val exportedFile = File (downloadDir, "${Date () . time}. mp4") if (exportedFile. exists () ) { exportedFile. delete () } encoder. setOutputFilePath (exportedFile. path) // if (bitmap == null) { // Log. w ("123", "") // return // } encoder. setOutputSize (width, height) encoder. startEncode () isRunning = true // 20, 50ms exportDisposable = Observable. interval (50, TimeUnit. MILLISECONDS) . map { createBitmapFromView () }. observeOn (AndroidSchedulers. mainThread () ) . subscribe { encoder. addFrame (it) } } override fun startRecord (fileDir: String) { } override fun stopRecord () { if (isRunning) { encoder. stopEncode () exportDisposable. dispose () } isRunning = false } override fun updateAudioState (audioRecord: Boolean) { TODO ("Not yet implemented") } private fun createBitmapFromView () : Bitmap { var cameraViewBitmap = cameraView. bitmap if (temperatureView. temperatureRegionMode != TemperatureView. REGION_MODE_CLEAN) { // temperature, measurement pointline measurement, temperature, bitmap cameraViewBitmap = BitmapUtils. mergeBitmap (cameraViewBitmap, temperatureView. regionAndValueBitmap, 0, 0) } val dstBitmap = if (cameraViewBitmap != null) { Bitmap. createScaledBitmap (cameraViewBitmap, width, height, true) } else { Bitmap. createBitmap (width, height, Bitmap. Config. ARGB_8888) } return dstBitmap } }